CREATE VIEW MOGUDI_KOL_ANBARHA_SUB AS SELECT        dbo.MOGO_AVL_KOL.CODE, dbo.UIIF(dbo.MOGO_AVL_KOL.SumOfMEG - ISNULL(dbo.mog_fr.MEG, 0), N'=', 0, NULL,                         dbo.MOGO_AVL_KOL.SumOfMEG - ISNULL(dbo.mog_fr.MEG, 0)) AS MAND, ISNULL(dbo.mog_fr.MEG, 0) AS MEGF, dbo.MOGO_AVL_KOL.SumOfMEG,                         dbo.MOGO_AVL_KOL.SumOfSumOfMABL_A - ISNULL(dbo.mog_fr.SumOfMABL_K, 0) AS MABLK, dbo.STUF_DEF.NAME, dbo.TCOD_VAHEDS.NAMES, ' ' AS KK,                          CAST(dbo.MOGO_AVL_KOL.CODE AS bigint) AS VCOD, dbo.STUF_DEF.KINDK FROM            dbo.TCOD_VAHEDS INNER JOIN                         dbo.MOGO_AVL_KOL RIGHT OUTER JOIN                         dbo.STUF_DEF ON dbo.MOGO_AVL_KOL.CODE = dbo.STUF_DEF.CODE LEFT OUTER JOIN                         dbo.mog_fr ON dbo.STUF_DEF.CODE = dbo.mog_fr.CODE ON dbo.TCOD_VAHEDS.CODE = dbo.STUF_DEF.VAHED WHERE (dbo.STUF_DEF.KINDK = 1) And (Not (dbo.MOGO_AVL_KOL.CODE Is Null))
